PREFIX in: <http://data.world/schema/insurance/>

SELECT ((SUM(?premiumValue) / COUNT(DISTINCT ?policy)) AS ?averagePolicySize)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .
    ?premium in:premiumAmount ?premiumValue .
  }
}

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmount
       (COALESCE(SUM(?lossPaymentVal), 0) +
        COALESCE(SUM(?lossReserveVal), 0) +
        COALESCE(SUM(?expensePaymentVal), 0) +
        COALESCE(SUM(?expenseReserveVal), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?ph .
    ?ph in:policyHolderId ?policyHolder .

    OPTIONAL {
      ?coverage in:hasPremiumAmount ?premium .
      ?premium in:premiumAmount ?premiumAmount .
    }

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lpAmt .
      BIND(xsd:decimal(?lpAmt) AS ?lossPaymentVal)
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lrAmt .
      BIND(xsd:decimal(?lrAmt) AS ?lossReserveVal)
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?epAmt .
      BIND(xsd:decimal(?epAmt) AS ?expensePaymentVal)
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?erAmt .
      BIND(xsd:decimal(?erAmt) AS ?expenseReserveVal)
    }
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolder ?premiumAmount
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolderId ?policyNumber (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?coverage in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .
    ?policy in:hasPolicyHolder ?policyHolder ;
            in:policyNumber ?policyNumber .
    ?policyHolder in:policyHolderId ?policyHolderId .
    ?premium in:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolderId ?policyNumber
ORDER BY ?policyHolderId ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid ?catastrophe ?agent
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:against ?pcd .
      ?pcd in:hasPolicy ?policy .
      OPTIONAL { ?policy in:policyNumber ?policyNumber . }
      OPTIONAL { 
        ?policy in:hasPolicyHolder ?ph .
        OPTIONAL { ?ph in:policyHolderId ?policyHolder . }
      }
      OPTIONAL {
        ?pcd in:hasPremiumAmount ?premium .
        OPTIONAL { ?premium in:premiumAmount ?premiumAmountPaid . }
      }
      OPTIONAL {
        ?policy in:soldByAgent ?ag .
        OPTIONAL { ?ag in:agentId ?agent . }
      }
    }

    OPTIONAL {
      ?claim in:hasCatastrophe ?cat .
      OPTIONAL { ?cat in:catastropheName ?catastrophe . }
    }

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      OPTIONAL { ?lp in:lossPaymentAmount ?lossPaymentAmount . }
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      OPTIONAL { ?lr in:lossReserveAmount ?lossReserveAmount . }
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      OPTIONAL { ?ep in:expensePaymentAmount ?expensePaymentAmount . }
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      OPTIONAL { ?er in:expenseReserveAmount ?expenseReserveAmount . }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent a in:Agent ;
           in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasExpenseReserve ?expenseReserve .

    ?expenseReserve a in:ExpenseReserve ;
                    in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
